import{_ as t,c as o,o as s,aM as i}from"./chunks/framework.ByOTD7qd.js";const u=JSON.parse('{"title":"OpenAI","description":"","frontmatter":{"title":"OpenAI","date":"2025-09-02T01:16:27.000Z"},"headers":[],"relativePath":"docs/providers/openai.md","filePath":"docs/providers/openai.md","lastUpdated":1763178133000}'),a={name:"docs/providers/openai.md"};function r(n,e,l,p,g,d){return s(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="openai-provider" tabindex="-1">OpenAI Provider <a class="header-anchor" href="#openai-provider" aria-label="Permalink to &quot;OpenAI Provider&quot;">​</a></h1><p>OpenAI offers industry-leading AI models including GPT-4, GPT-3.5, and the reasoning-focused o1 series.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><h3 id="create-an-api-key" tabindex="-1">Create an API Key <a class="header-anchor" href="#create-an-api-key" aria-label="Permalink to &quot;Create an API Key&quot;">​</a></h3><ol><li>Visit <a href="https://platform.openai.com" target="_blank" rel="noreferrer">https://platform.openai.com</a></li><li>Sign up or log in</li><li>Navigate to <strong>API keys</strong> section</li><li>Click <strong>Create new secret key</strong></li><li><strong>Copy the key immediately</strong> (it won&#39;t be shown again)</li><li><strong>Name it</strong> for tracking (e.g., &quot;Kelivo Mobile&quot;)</li></ol><h3 id="add-to-kelivo" tabindex="-1">Add to Kelivo <a class="header-anchor" href="#add-to-kelivo" aria-label="Permalink to &quot;Add to Kelivo&quot;">​</a></h3><ol><li>Go to <strong>Settings → Providers</strong></li><li>Tap <strong>Add Provider</strong> or <strong>+</strong></li><li>Fill in details: <ul><li><strong>Name</strong>: &quot;OpenAI&quot; or custom name</li><li><strong>Provider Type</strong>: OpenAI</li><li><strong>Base URL</strong>: <code>https://api.openai.com/v1</code> (default)</li><li><strong>API Key</strong>: Paste your key</li><li><strong>Default Model</strong>: gpt-4o (or your preferred model)</li></ul></li><li><strong>Save</strong></li></ol><h3 id="test-connection" tabindex="-1">Test Connection <a class="header-anchor" href="#test-connection" aria-label="Permalink to &quot;Test Connection&quot;">​</a></h3><p>Send a test message to verify:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User: Hello!</span></span>
<span class="line"><span>AI: Hello! How can I help you today?</span></span></code></pre></div><p>If it works, you&#39;re all set!</p><h2 id="available-models" tabindex="-1">Available Models <a class="header-anchor" href="#available-models" aria-label="Permalink to &quot;Available Models&quot;">​</a></h2><h3 id="gpt-4-series-most-capable" tabindex="-1">GPT-4 Series (Most Capable) <a class="header-anchor" href="#gpt-4-series-most-capable" aria-label="Permalink to &quot;GPT-4 Series (Most Capable)&quot;">​</a></h3><p><strong>gpt-4o</strong> (Recommended)</p><ul><li><strong>Best for</strong>: General use, vision, most tasks</li><li><strong>Context</strong>: 128K tokens</li><li><strong>Features</strong>: Text, vision, function calling, JSON mode</li><li><strong>Speed</strong>: Fast</li><li><strong>Cost</strong>: Moderate</li><li><strong>Use when</strong>: You need high quality and speed</li></ul><p><strong>gpt-4-turbo</strong></p><ul><li><strong>Best for</strong>: Complex tasks, long documents</li><li><strong>Context</strong>: 128K tokens</li><li><strong>Features</strong>: Text, vision, function calling</li><li><strong>Speed</strong>: Moderate</li><li><strong>Cost</strong>: Higher</li><li><strong>Use when</strong>: You need maximum capability</li></ul><p><strong>gpt-4</strong> (Original)</p><ul><li><strong>Best for</strong>: Consistency, proven reliability</li><li><strong>Context</strong>: 8K tokens</li><li><strong>Features</strong>: Text only</li><li><strong>Speed</strong>: Slower</li><li><strong>Cost</strong>: High</li><li><strong>Use when</strong>: Legacy applications</li></ul><h3 id="gpt-3-5-series-fast-economical" tabindex="-1">GPT-3.5 Series (Fast &amp; Economical) <a class="header-anchor" href="#gpt-3-5-series-fast-economical" aria-label="Permalink to &quot;GPT-3.5 Series (Fast &amp; Economical)&quot;">​</a></h3><p><strong>gpt-3.5-turbo</strong></p><ul><li><strong>Best for</strong>: Quick tasks, high volume, cost-sensitive use</li><li><strong>Context</strong>: 16K tokens</li><li><strong>Features</strong>: Text, function calling</li><li><strong>Speed</strong>: Very fast</li><li><strong>Cost</strong>: Low</li><li><strong>Use when</strong>: Simple tasks, speed matters</li></ul><h3 id="o1-series-reasoning-models" tabindex="-1">o1 Series (Reasoning Models) <a class="header-anchor" href="#o1-series-reasoning-models" aria-label="Permalink to &quot;o1 Series (Reasoning Models)&quot;">​</a></h3><p><strong>o1-preview</strong></p><ul><li><strong>Best for</strong>: Complex reasoning, math, code, science</li><li><strong>Context</strong>: 128K tokens</li><li><strong>Features</strong>: Deep reasoning, no streaming</li><li><strong>Speed</strong>: Slower (thinks before responding)</li><li><strong>Cost</strong>: Higher</li><li><strong>Use when</strong>: Problems require step-by-step thinking</li></ul><p><strong>o1-mini</strong></p><ul><li><strong>Best for</strong>: Coding, STEM problems, cost-conscious reasoning</li><li><strong>Context</strong>: 128K tokens</li><li><strong>Features</strong>: Faster reasoning, more affordable</li><li><strong>Speed</strong>: Moderate</li><li><strong>Cost</strong>: Lower than o1-preview</li><li><strong>Use when</strong>: Coding or math on a budget</li></ul><h3 id="model-comparison" tabindex="-1">Model Comparison <a class="header-anchor" href="#model-comparison" aria-label="Permalink to &quot;Model Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th>Speed</th><th>Quality</th><th>Cost</th><th>Vision</th><th>Best Use Case</th></tr></thead><tbody><tr><td>gpt-4o</td><td>⚡⚡⚡</td><td>⭐⭐⭐⭐⭐</td><td>💰💰</td><td>✅</td><td>General purpose</td></tr><tr><td>gpt-4-turbo</td><td>⚡⚡</td><td>⭐⭐⭐⭐⭐</td><td>💰💰💰</td><td>✅</td><td>Long documents</td></tr><tr><td>gpt-3.5-turbo</td><td>⚡⚡⚡⚡</td><td>⭐⭐⭐</td><td>💰</td><td>❌</td><td>Simple tasks</td></tr><tr><td>o1-preview</td><td>⚡</td><td>⭐⭐⭐⭐⭐</td><td>💰💰💰💰</td><td>❌</td><td>Complex reasoning</td></tr><tr><td>o1-mini</td><td>⚡⚡</td><td>⭐⭐⭐⭐</td><td>💰💰</td><td>❌</td><td>Coding, STEM</td></tr></tbody></table><h2 id="features-capabilities" tabindex="-1">Features &amp; Capabilities <a class="header-anchor" href="#features-capabilities" aria-label="Permalink to &quot;Features &amp; Capabilities&quot;">​</a></h2><h3 id="vision-multimodal" tabindex="-1">Vision (Multimodal) <a class="header-anchor" href="#vision-multimodal" aria-label="Permalink to &quot;Vision (Multimodal)&quot;">​</a></h3><p><strong>Supported models</strong>: gpt-4o, gpt-4-turbo, gpt-4-vision-preview</p><p><strong>Use cases</strong>:</p><ul><li>Describe images</li><li>Extract text from screenshots</li><li>Analyze charts and diagrams</li><li>Answer questions about photos</li><li>Generate image captions</li></ul><p><strong>Example</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User: [attaches screenshot] What&#39;s in this error message?</span></span>
<span class="line"><span>AI: The error shows a &quot;Module not found&quot; exception...</span></span></code></pre></div><p><strong>Tips</strong>:</p><ul><li>High-resolution images cost more tokens</li><li>Consider resizing large images</li><li>Works with multiple images in one message</li></ul><h3 id="function-calling" tabindex="-1">Function Calling <a class="header-anchor" href="#function-calling" aria-label="Permalink to &quot;Function Calling&quot;">​</a></h3><p><strong>Supported models</strong>: All except o1 series (limited support)</p><p><strong>Use cases</strong>:</p><ul><li>Structured data extraction</li><li>API integrations</li><li>Tool usage (web search, calculations)</li><li>Database queries</li></ul><p><strong>Example</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User: What&#39;s the weather in Tokyo?</span></span>
<span class="line"><span>AI: [calls get_weather function with location=&quot;Tokyo&quot;]</span></span>
<span class="line"><span>AI: It&#39;s currently 22°C and partly cloudy in Tokyo.</span></span></code></pre></div><h3 id="json-mode" tabindex="-1">JSON Mode <a class="header-anchor" href="#json-mode" aria-label="Permalink to &quot;JSON Mode&quot;">​</a></h3><p><strong>Supported models</strong>: gpt-4o, gpt-4-turbo, gpt-3.5-turbo</p><p><strong>Use cases</strong>:</p><ul><li>Structured output</li><li>Data extraction</li><li>API responses</li></ul><p><strong>Enable</strong>: Add to request (via custom prompts or provider settings)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;response_format&quot;: { &quot;type&quot;: &quot;json_object&quot; }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>Example</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User: Extract: &quot;John works at Google as a developer&quot;</span></span>
<span class="line"><span>AI: {&quot;name&quot;: &quot;John&quot;, &quot;company&quot;: &quot;Google&quot;, &quot;role&quot;: &quot;developer&quot;}</span></span></code></pre></div><h3 id="streaming" tabindex="-1">Streaming <a class="header-anchor" href="#streaming" aria-label="Permalink to &quot;Streaming&quot;">​</a></h3><p><strong>All models support streaming</strong> for real-time responses.</p><p><strong>Benefits</strong>:</p><ul><li>Faster perceived response time</li><li>Can stop generation mid-response</li><li>Better user experience</li></ul><p>Kelivo enables streaming by default.</p><h2 id="configuration-tips" tabindex="-1">Configuration Tips <a class="header-anchor" href="#configuration-tips" aria-label="Permalink to &quot;Configuration Tips&quot;">​</a></h2><h3 id="temperature-settings" tabindex="-1">Temperature Settings <a class="header-anchor" href="#temperature-settings" aria-label="Permalink to &quot;Temperature Settings&quot;">​</a></h3><p><strong>For different models</strong>:</p><ul><li><strong>GPT-4o, GPT-4</strong>: 0.7 (default, balanced)</li><li><strong>GPT-3.5</strong>: 0.5-0.7 (more focused)</li><li><strong>o1 series</strong>: Fixed internally (don&#39;t adjust)</li></ul><p><strong>For different tasks</strong>:</p><ul><li><strong>Code</strong>: 0.2-0.3 (deterministic)</li><li><strong>Writing</strong>: 0.8-1.0 (creative)</li><li><strong>Analysis</strong>: 0.3-0.5 (focused)</li><li><strong>Brainstorming</strong>: 1.0-1.2 (diverse)</li></ul><h3 id="max-tokens" tabindex="-1">Max Tokens <a class="header-anchor" href="#max-tokens" aria-label="Permalink to &quot;Max Tokens&quot;">​</a></h3><p>Control response length:</p><ul><li><strong>Short answers</strong>: 256-512 tokens</li><li><strong>Medium</strong>: 1024-2048 tokens</li><li><strong>Long form</strong>: 4096+ tokens</li></ul><p><strong>Tip</strong>: Leave headroom in context window for conversation history.</p><h3 id="system-prompts" tabindex="-1">System Prompts <a class="header-anchor" href="#system-prompts" aria-label="Permalink to &quot;System Prompts&quot;">​</a></h3><p>OpenAI models respond well to:</p><ul><li>Clear role definitions</li><li>Numbered instructions</li><li>Examples (few-shot)</li><li>Explicit formatting requests</li></ul><p><strong>Example</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You are a senior Python developer. Provide clean, well-documented code with type hints. Always consider edge cases and error handling.</span></span></code></pre></div><h2 id="pricing-rate-limits" tabindex="-1">Pricing &amp; Rate Limits <a class="header-anchor" href="#pricing-rate-limits" aria-label="Permalink to &quot;Pricing &amp; Rate Limits&quot;">​</a></h2><h3 id="pricing-as-of-2025" tabindex="-1">Pricing (as of 2025) <a class="header-anchor" href="#pricing-as-of-2025" aria-label="Permalink to &quot;Pricing (as of 2025)&quot;">​</a></h3><p><strong>Input/Output tokens</strong>:</p><ul><li><strong>gpt-4o</strong>: $2.50/$10.00 per 1M tokens</li><li><strong>gpt-4-turbo</strong>: $10.00/$30.00 per 1M tokens</li><li><strong>gpt-3.5-turbo</strong>: $0.50/$1.50 per 1M tokens</li><li><strong>o1-preview</strong>: $15.00/$60.00 per 1M tokens</li><li><strong>o1-mini</strong>: $3.00/$12.00 per 1M tokens</li></ul><p><strong>Note</strong>: Prices may change. Check <a href="https://openai.com/pricing" target="_blank" rel="noreferrer">https://openai.com/pricing</a> for current rates.</p><h3 id="rate-limits" tabindex="-1">Rate Limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate Limits&quot;">​</a></h3><p><strong>Free tier</strong>:</p><ul><li>3 requests per minute (RPM)</li><li>40,000 tokens per minute (TPM)</li><li>200 requests per day (RPD)</li></ul><p><strong>Paid tier 1</strong>:</p><ul><li>3,500 RPM (GPT-4)</li><li>90,000 TPM</li><li>Higher limits after usage</li></ul><p><strong>Paid tier 2+</strong>:</p><ul><li>5,000+ RPM</li><li>450,000+ TPM</li><li>Scale with usage</li></ul><p><strong>Tip</strong>: Upgrade to paid tier for better limits. Monitor usage in OpenAI dashboard.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="rate-limit-errors-429" tabindex="-1">Rate Limit Errors (429) <a class="header-anchor" href="#rate-limit-errors-429" aria-label="Permalink to &quot;Rate Limit Errors (429)&quot;">​</a></h3><p><strong>Error</strong>: &quot;Rate limit exceeded&quot;</p><p><strong>Solutions</strong>:</p><ol><li><strong>Wait</strong>: Limits reset per minute</li><li><strong>Upgrade tier</strong>: Use more, get higher limits</li><li><strong>Switch model</strong>: Use GPT-3.5 if GPT-4 is limited</li><li><strong>Reduce frequency</strong>: Add delays between requests</li></ol><h3 id="invalid-api-key-401" tabindex="-1">Invalid API Key (401) <a class="header-anchor" href="#invalid-api-key-401" aria-label="Permalink to &quot;Invalid API Key (401)&quot;">​</a></h3><p><strong>Error</strong>: &quot;Incorrect API key provided&quot;</p><p><strong>Solutions</strong>:</p><ol><li><strong>Verify key</strong>: Copy entire key, no extra spaces</li><li><strong>Check status</strong>: Ensure key hasn&#39;t been revoked</li><li><strong>Regenerate</strong>: Create new key if lost</li><li><strong>Organization</strong>: Verify org access if applicable</li></ol><h3 id="model-not-found-404" tabindex="-1">Model Not Found (404) <a class="header-anchor" href="#model-not-found-404" aria-label="Permalink to &quot;Model Not Found (404)&quot;">​</a></h3><p><strong>Error</strong>: &quot;The model &#39;xyz&#39; does not exist&quot;</p><p><strong>Solutions</strong>:</p><ol><li><strong>Check name</strong>: Use exact model names (e.g., &quot;gpt-4o&quot; not &quot;gpt4o&quot;)</li><li><strong>Access</strong>: Verify your account has access (o1 requires waitlist approval)</li><li><strong>Region</strong>: Some models limited to certain regions</li></ol><h3 id="context-length-exceeded" tabindex="-1">Context Length Exceeded <a class="header-anchor" href="#context-length-exceeded" aria-label="Permalink to &quot;Context Length Exceeded&quot;">​</a></h3><p><strong>Error</strong>: &quot;This model&#39;s maximum context length is...&quot;</p><p><strong>Solutions</strong>:</p><ol><li><strong>Shorten input</strong>: Reduce conversation history</li><li><strong>Use larger model</strong>: GPT-4-turbo has 128K context</li><li><strong>Summarize</strong>: Condense old messages</li><li><strong>Clear history</strong>: Start fresh conversation</li></ol><h3 id="slow-responses" tabindex="-1">Slow Responses <a class="header-anchor" href="#slow-responses" aria-label="Permalink to &quot;Slow Responses&quot;">​</a></h3><p><strong>Solutions</strong>:</p><ol><li><strong>Use faster model</strong>: GPT-3.5 or gpt-4o</li><li><strong>Streaming</strong>: Should be enabled by default</li><li><strong>Reduce load</strong>: Shorter prompts, less context</li><li><strong>Check status</strong>: <a href="https://status.openai.com" target="_blank" rel="noreferrer">https://status.openai.com</a></li></ol><h2 id="advanced-features" tabindex="-1">Advanced Features <a class="header-anchor" href="#advanced-features" aria-label="Permalink to &quot;Advanced Features&quot;">​</a></h2><h3 id="organization-id" tabindex="-1">Organization ID <a class="header-anchor" href="#organization-id" aria-label="Permalink to &quot;Organization ID&quot;">​</a></h3><p>For teams with multiple projects:</p><ol><li>Find your org ID: <a href="https://platform.openai.com/account/organization" target="_blank" rel="noreferrer">https://platform.openai.com/account/organization</a></li><li>Add custom header in Kelivo:<div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;OpenAI-Organization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org-xxxxxxxxxxxxx&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li></ol><h3 id="azure-openai" tabindex="-1">Azure OpenAI <a class="header-anchor" href="#azure-openai" aria-label="Permalink to &quot;Azure OpenAI&quot;">​</a></h3><p>Use OpenAI models via Azure:</p><p><strong>Base URL</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://YOUR-RESOURCE-NAME.openai.azure.com</span></span></code></pre></div><p><strong>API Key</strong>: Azure OpenAI key (not OpenAI key)</p><p><strong>Model Deployment</strong>: Use your deployment name</p><p>See <a href="/docs/assistant/custom-requests">Custom Requests</a> for details.</p><h3 id="openai-compatible-providers" tabindex="-1">OpenAI-Compatible Providers <a class="header-anchor" href="#openai-compatible-providers" aria-label="Permalink to &quot;OpenAI-Compatible Providers&quot;">​</a></h3><p>Use gateways offering OpenAI-compatible APIs:</p><p><strong>Examples</strong>:</p><ul><li><strong>OpenRouter</strong>: Aggregates many providers</li><li><strong>Together AI</strong>: Open-source models</li><li><strong>Groq</strong>: Fast inference for open models</li><li><strong>Anyscale</strong>: Llama and Mistral models</li></ul><p><strong>Setup</strong>: Change base URL, use their API key</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><h3 id="model-selection" tabindex="-1">Model Selection <a class="header-anchor" href="#model-selection" aria-label="Permalink to &quot;Model Selection&quot;">​</a></h3><ul><li><strong>Default</strong>: gpt-4o for most users</li><li><strong>Budget</strong>: gpt-3.5-turbo for high volume</li><li><strong>Complex tasks</strong>: gpt-4-turbo or o1-preview</li><li><strong>Code</strong>: o1-mini or gpt-4o</li><li><strong>Speed</strong>: gpt-3.5-turbo or gpt-4o</li></ul><h3 id="cost-optimization" tabindex="-1">Cost Optimization <a class="header-anchor" href="#cost-optimization" aria-label="Permalink to &quot;Cost Optimization&quot;">​</a></h3><ol><li><strong>Right-size model</strong>: Don&#39;t use GPT-4 for simple tasks</li><li><strong>Shorten prompts</strong>: Remove unnecessary context</li><li><strong>Manage history</strong>: Limit conversation length</li><li><strong>Use caching</strong>: Reuse system prompts (provider-level)</li><li><strong>Monitor usage</strong>: Check OpenAI dashboard regularly</li></ol><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ol><li><strong>Protect API keys</strong>: Never share or commit to repos</li><li><strong>Rotate keys</strong>: Periodic rotation policy</li><li><strong>Use separate keys</strong>: Different keys for dev/prod</li><li><strong>Monitor usage</strong>: Watch for unusual activity</li><li><strong>Set spending limits</strong>: In OpenAI dashboard</li></ol><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><ol><li><strong>Enable streaming</strong>: For better UX</li><li><strong>Parallel requests</strong>: For independent tasks</li><li><strong>Appropriate timeouts</strong>: 60s for GPT-4, 30s for GPT-3.5</li><li><strong>Retry logic</strong>: Handle transient failures</li></ol><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><h3 id="official-documentation" tabindex="-1">Official Documentation <a class="header-anchor" href="#official-documentation" aria-label="Permalink to &quot;Official Documentation&quot;">​</a></h3><ul><li>OpenAI Platform: <a href="https://platform.openai.com" target="_blank" rel="noreferrer">https://platform.openai.com</a></li><li>API Reference: <a href="https://platform.openai.com/docs/api-reference" target="_blank" rel="noreferrer">https://platform.openai.com/docs/api-reference</a></li><li>Pricing: <a href="https://openai.com/pricing" target="_blank" rel="noreferrer">https://openai.com/pricing</a></li><li>Status: <a href="https://status.openai.com" target="_blank" rel="noreferrer">https://status.openai.com</a></li></ul><h3 id="community" tabindex="-1">Community <a class="header-anchor" href="#community" aria-label="Permalink to &quot;Community&quot;">​</a></h3><ul><li>OpenAI Forum: <a href="https://community.openai.com" target="_blank" rel="noreferrer">https://community.openai.com</a></li><li>Discord: Official OpenAI community</li><li>Reddit: r/OpenAI</li></ul><h3 id="learning" tabindex="-1">Learning <a class="header-anchor" href="#learning" aria-label="Permalink to &quot;Learning&quot;">​</a></h3><ul><li>OpenAI Cookbook: Code examples</li><li>Prompt Engineering Guide: Best practices</li><li>Model documentation: Capabilities and limits</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Configure your <a href="/docs/assistant/basics">Assistant</a> with OpenAI</li><li>Write effective <a href="/docs/assistant/prompts">Prompts</a> for GPT models</li><li>Explore <a href="/docs/assistant/custom-requests">Custom Requests</a> for advanced setups</li><li>Compare with other providers: <a href="/docs/providers/anthropic">Anthropic</a>, <a href="/docs/providers/google">Google</a></li></ul><p>Need help? Check the <a href="/docs/getting-started/faq">FAQ</a> or <a href="https://github.com/Chevey339/kelivo/issues" target="_blank" rel="noreferrer">open an issue</a>.</p>`,140)])])}const h=t(a,[["render",r]]);export{u as __pageData,h as default};
